DECLARE
  CURSOR c_emp IS SELECT ENAME, SAL FROM EMP;
BEGIN
  FOR r IN c_emp LOOP
    IF r.SAL < 2000 THEN CONTINUE; END IF;
    DBMS_OUTPUT.PUT_LINE(r.ENAME || ': ' || r.SAL);
  END LOOP;
END;

