DECLARE
  s NUMBER := 0; i NUMBER := 1;
BEGIN
  LOOP
    s := s + i;
    EXIT WHEN s > 50;
    DBMS_OUTPUT.PUT(i || ' ');
    i := i + 1;
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
END;

DECLARE
  TYPE num_list IS TABLE OF NUMBER;
  vals num_list := num_list(10, 20, -1, 40);
BEGIN
  FOR i IN 1..vals.COUNT LOOP
    IF vals(i) < 0 THEN EXIT; END IF;
    DBMS_OUTPUT.PUT_LINE(vals(i));
  END LOOP;
END;

